INSERT INTO public.events (id,user_id,title,visibility,created_at,updated_at,deleted_at,long_description,short_description) VALUES ('4005ad0a-82c8-5071-9f76-804e753738a7', NULL, 'Palm Sunday', 'system', DEFAULT, DEFAULT, '2020-11-03T10:12:43.000Z', 'The [beginning of Holy Week](https://libguides.asu.edu), recalled with the blessing of palm branches to signify the crowds who welcomed Jesus.', 'The commemoration of Jesus'' triumphal entry into Jerusalem.'), ('87f19d2c-6490-5bfc-b551-bacabbea7ab3', NULL, 'Easter', 'system', DEFAULT, DEFAULT, '2020-06-26T05:28:37.000Z', 'The [holiest period of the Church year](https://seaportshrine.org), including the Easter Vigil—the first liturgical celebration of the Resurrection—and Easter Sunday.', 'The celebration of the Passion, Death, and Resurrection of Jesus.'), ('ee6511da-c2f8-569e-ac7e-8c323a022ac3', NULL, 'Feast of the Ascension', 'system', DEFAULT, DEFAULT, '2020-09-25T20:56:25.000Z', 'Occurring 40 days after the Resurrection, this feast marks the moment [Jesus ascended bodily into heaven](https://www.christianity.com) in the presence of His apostles.', 'Celebrates Jesus Christ ascending into heaven.'), ('1673bb82-e1a3-57a0-9e40-2ba1a6518133', NULL, 'Pentecost', 'system', DEFAULT, DEFAULT, '2020-07-03T18:25:44.000Z', 'Celebrated 50 days after Easter, it commemorates the [Holy Spirit coming to the disciples](https://libguides.asu.edu) as ''tongues of fire,'' marking the birth of the Church.', 'The descent of the Holy Spirit upon the Apostles.'), ('77a23d72-77dc-5dec-a06d-22ea5e1da368', NULL, 'Christmas', 'system', DEFAULT, DEFAULT, '2020-01-09T12:00:43.000Z', 'A major solemnity celebrating the [birth of Jesus Christ](https://www.vaticannews.va) in Bethlehem. It marks the end of Advent and the start of the Christmas season.', 'The Nativity of Jesus Christ and the beginning of Christmastide.'), ('39c387a6-be78-5de9-afec-e80f0a08bd25', NULL, 'Feast of Corpus Christi', 'system', DEFAULT, DEFAULT, '2020-08-12T19:56:29.000Z', 'A feast honoring the real presence of the [body and blood of Jesus](https://github.com) in the Eucharist, traditionally celebrated after Trinity Sunday.', 'The Solemnity of the Most Holy Body and Blood of Christ.'), ('9ae6a42f-4596-5693-85fd-af4b532ff143', NULL, 'First Sunday of Advent', 'system', DEFAULT, DEFAULT, '2020-11-03T10:23:20.000Z', 'Marks the start of the [Advent season](https://www.usccb.org worship/liturgical-year/advent), a time of expectant waiting and preparation for both the celebration of the Nativity of Christ at Christmas and the return of Christ at the Second Coming.', 'The beginning of the liturgical year and a season of preparation.'), ('31bf359f-c31c-5f61-9c9a-4ae7b52d32e8', NULL, 'Solemnity of Christ the King', 'system', DEFAULT, DEFAULT, '2020-12-20T12:01:32.000Z', 'The final Sunday of the [liturgical year](https://www.facebook.com), emphasizing Christ''s sovereignty over the universe.', 'Honors Jesus Christ as Lord of all creation.'), ('c607989d-df79-5e32-b38a-fce162d97b92', NULL, 'Totensonntag', 'system', DEFAULT, DEFAULT, '2020-11-19T11:02:58.000Z', 'The last Sunday before Advent in German Lutheran traditions, dedicated to [remembering those who have died](https://www.christianity.com) in the past year.', 'Sunday of the Dead; a German Protestant day of remembrance.'), ('066cad65-2b3b-57c5-89b0-33b98b132566', NULL, 'Solemnity of Mary, Mother of God', 'system', DEFAULT, DEFAULT, '2020-11-23T10:26:28.000Z', 'Observed on January 1st, this [Holy Day of Obligation](https://www.xavier.edu) honors the Blessed Virgin Mary as the ''Theotokos'' (God-bearer).', 'A celebration of Mary''s motherhood of Jesus.'), ('73722b3b-36f4-53a5-9b87-6b9893fe2f76', NULL, 'Epiphany of the Lord', 'system', DEFAULT, DEFAULT, '2020-09-25T08:22:45.000Z', 'Celebrates the [manifestation of the divine nature of Jesus](https://library.framingham.edu) to the Magi, signifying that the savior has come for all nations.', 'Commemorates the revelation of Christ to the world.'), ('e4021b81-e0ab-5181-bab7-75f5069116d7', NULL, 'Feast of the Transfiguration', 'system', DEFAULT, DEFAULT, '2020-05-13T16:52:12.000Z', 'Recalls the event where [Jesus’ physical appearance became brilliant](https://laverne.edu) as He spoke with Moses and Elijah, revealing His divine glory.', 'Commemorates Jesus'' radiant appearance on Mount Tabor.'), ('5126a92f-2dab-526b-ae58-f67cb50f1394', NULL, 'Feast of the Assumption', 'system', DEFAULT, DEFAULT, '2020-04-28T15:40:37.000Z', 'A [Catholic solemnity](https://www.xavier.edu) on August 15th observing the Blessed Virgin Mary''s assumption into heavenly glory.', 'Celebrates Mary being taken body and soul into heaven.'), ('18b58afd-b025-5d7e-9cde-c923dd0c114d', NULL, 'The Exaltation of the Holy Cross', 'system', DEFAULT, DEFAULT, '2020-02-10T13:28:18.000Z', 'Commemorates the finding and [annual elevation of the cross](https://buildfaith.org) used in the crucifixion of Jesus Christ.', 'Also known as Holy Rood Day, honoring the Cross of Christ.'), ('14f1cdde-c4dc-5a21-adda-89985084a9d0', NULL, 'Reformation Day', 'system', DEFAULT, DEFAULT, '2020-09-09T20:54:10.000Z', 'Observed on October 31st, marking the anniversary of [Martin Luther nailing the 95 Theses](https://www.faithward.org) to the church door in Wittenberg.', 'Commemorates the start of the Protestant Reformation.'), ('aa2a278d-d33f-5cdb-879d-bbc3820311dc', NULL, 'All Saints'' Day', 'system', DEFAULT, DEFAULT, '2020-10-26T22:11:18.000Z', 'A day to honor all those who have achieved [lives of holiness](https://libguides.asu.edu) or were martyred for their faith. Also referred to as Solemnity of All Saints.', 'Honoring all saints, known and unknown.'), ('f7c9837d-2a66-52c3-a1de-f99fa64a0c26', NULL, 'Feast of the Immaculate Conception', 'system', DEFAULT, DEFAULT, '2020-04-20T15:04:15.000Z', 'A [Holy Day of Obligation](https://www.bbcatholic.org.au) on December 8th, celebrating the belief that Mary was preserved from original sin from her conception.', 'Celebrates Mary being conceived without original sin.');
