INSERT INTO public.traditions (id,title,short_description,long_description,created_at,updated_at,visibility,deleted_at,user_id,notes,is_default,event_id,operations) VALUES ('c4f0fda5-f0a7-532f-9a5f-a5e52bad00b6', 'Solemnity Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-07-19T06:35:40.000Z', NULL, 'Te sic et maxim ent ferreum cupidium cyrenaicosten, si sententa hoc quam magnus placetiam.', 't', NULL, '["offset-days:0"]'), ('4a425ee8-157c-52d3-9221-c30e5835edd7', 'Solemnity Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-06-26T05:24:39.000Z', NULL, 'Tentamentan hoc ut sectetur magis, neque quae disputamic autem eturae.', 'f', NULL, '["offset-days:-1"]'), ('72e9e7e3-831f-51c8-88c4-0e784a800390', 'Advent Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-11-23T23:11:40.000Z', NULL, 'Bonum voluptas quamvis haec neglegante eo, maleduntur ut neque nec falsis ipsos ex doctrinis.', 't', NULL, '["offset-days:0"]'), ('eca7e37f-f6a4-57b2-b924-68be1162f538', 'Advent Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-04-04T16:01:47.000Z', NULL, 'Et opho genus satistim reque nec.', 'f', NULL, '["offset-days:-1"]'), ('6a42c4dc-3cb8-5301-8998-3fffc5d14479', 'Corpus Christi Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-09-13T20:10:04.000Z', NULL, 'Privamurum cuius nati laborem virtutem suum.', 't', NULL, '["offset-days:0"]'), ('9cee602c-5d32-5cab-a1fb-96ad9e1e0f3c', 'Corpus Christi Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-04-08T04:00:13.000Z', NULL, 'Hominpotes assentias pondeniquem cognitat dolor libere.', 'f', NULL, '["offset-days:-1"]'), ('e1ceedfa-14a0-5620-97f6-07bde2e6f569', 'Christmas Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-06-14T17:52:04.000Z', NULL, 'Sempiterta quem magis proprius quo.', 't', NULL, '["offset-days:0"]'), ('67c187dc-29cc-512c-8bb4-b6edc63706eb', 'Christmas Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-06-22T05:32:38.000Z', NULL, 'As quod satis efficiliae diu torquatum.', 'f', NULL, '["offset-days:-1"]'), ('800b9de0-0216-544e-b2ea-5daaa60b8a79', 'Pentecost Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-04-16T03:40:47.000Z', NULL, 'Aut in eius etiam sit quae.', 't', NULL, '["offset-days:0"]'), ('a76d7dc8-fa77-5063-9fc7-7a1417c4b1ac', 'Pentecost Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-08-24T07:46:26.000Z', NULL, 'Et rationi sicultimar terminus non amus perita.', 'f', NULL, '["offset-days:-1"]'), ('43ceae93-a572-5056-a976-66f13a651a70', 'Ascension Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-09-09T20:57:18.000Z', NULL, 'Ne discipi evolut alia primum non, consenteneb qui quaerita causa haberti.', 't', NULL, '["offset-days:0"]'), ('b01e27a1-15f7-5625-94ef-22ea4cbb922d', 'Ascension Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-06-10T05:22:24.000Z', NULL, 'Beateque quandam omnino non abundia mox.', 'f', NULL, '["offset-days:-1"]'), ('0d8062e1-a885-5da7-a38c-349c807082b9', 'Palm Sunday Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-07-11T06:19:49.000Z', NULL, 'Util potere non quod et ullum a defent, expetentum parvam antiopam quarum inem.', 't', NULL, '["offset-days:0"]'), ('acf9aef3-a727-5591-9d7e-92cf2d2beb34', 'Palm Sunday Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-08-04T19:58:40.000Z', NULL, 'De p et per desperandri quae rebus.', 'f', NULL, '["offset-days:-1"]'), ('1145ccc3-77dd-5212-9004-b7dbf3dd184c', 'Easter Tradish 1', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-12-12T23:14:27.000Z', NULL, 'Conquisquam omoria eum numquam omnesque, sit ad parantium seritarbit electare est.', 't', NULL, '["offset-days:0"]'), ('4a065791-1c7a-52b6-9140-46b08a483b77', 'Easter Tradish 2', 'The virvonta or virpominen (meaning the act of refreshment or wishing) is performed by Finnish children on Palm Sunday to wish well to the households.', 'Virvonta was formed from a mixture of blessing customs that had been maintained by Orthodox Christians in Eastern Finland and a Western Finnish trulli tradition that is akin to the Swedish easter witch practice[3][4][5] with pre-Christian roots.', DEFAULT, DEFAULT, 'system', '2020-12-28T23:59:21.000Z', NULL, 'Medium cur aliquando anim multi deserrorib iucunt, iucuntatem sine et domest de.', 'f', NULL, '["offset-days:-1"]');
